<script setup lang="ts">
import { Bell, CheckCheck } from '@lucide/vue'; import type { UserNotification } from '~/types/blog'; import { formatRelativeTime } from '~/utils/date';
const userStore=useStore.user(); const api=useApiClient(); const items=ref<UserNotification[]>([]); const loading=ref(false); const page=ref(0); const total=ref(0);
if(!userStore.isAuthenticated) await navigateTo('/');
const load=async()=>{loading.value=true;try{const r=await api.fetchNotifications(page.value,20);if(r.success){items.value=r.data.items;total.value=r.data.totalItems}}finally{loading.value=false}};
const openItem=async(item:UserNotification)=>{if(!item.read){await api.markNotificationRead(item.id);item.read=true}if(item.actionUrl)await navigateTo(item.actionUrl)};
const readAll=async()=>{await api.markAllNotificationsRead();items.value.forEach(i=>i.read=true)};
await load(); useSeoMeta({title:'通知中心'});
</script>
<template><BlogPageLayout><section class="notice-page"><header><div><h1><Bell :size="24"/>通知中心</h1><p>评论回复、系统提醒和账号安全消息</p></div><button v-if="items.some(i=>!i.read)" type="button" @click="readAll"><CheckCheck :size="16"/>全部已读</button></header><div v-if="loading" class="empty">加载中…</div><div v-else-if="!items.length" class="empty">暂无通知</div><button v-for="item in items" :key="item.id" type="button" class="notice" :class="{'is-unread':!item.read}" @click="openItem(item)"><span class="dot"/><span class="body"><strong>{{ item.title }}</strong><span>{{ item.content }}</span><small>{{ formatRelativeTime(item.createdAt) }}</small></span></button></section></BlogPageLayout></template>
<style scoped>.notice-page{max-width:900px;margin:30px auto;padding:24px;background:var(--bg-card);border:1px solid var(--border-color);border-radius:18px}.notice-page header{display:flex;justify-content:space-between;gap:16px;align-items:center;margin-bottom:20px}.notice-page h1{display:flex;align-items:center;gap:10px;margin:0}.notice-page p{color:var(--text-muted)}header button{display:flex;gap:6px;align-items:center;border:0;background:transparent;color:var(--theme-color);cursor:pointer}.notice{width:100%;display:flex;gap:14px;text-align:left;padding:18px 10px;border:0;border-top:1px solid var(--border-color);background:transparent;color:inherit;cursor:pointer}.notice:hover{background:color-mix(in srgb,var(--theme-color) 5%,transparent)}.dot{width:8px;height:8px;margin-top:7px;border-radius:50%;background:transparent}.is-unread .dot{background:var(--theme-color)}.body{display:grid;gap:6px}.body span,.body small{color:var(--text-muted)}.empty{text-align:center;padding:60px;color:var(--text-muted)}</style>
